import React, { useEffect, useState } from "react";
import axios from "axios";

const API_URL = "http://localhost:5000/api/admin";

function AdminPanel({
  candidateForm,
  setCandidateForm,
  onSave,
  editId,
  setEditId,
  onDelete,
  candidates,
  theme,
}) {
  const [codes, setCodes] = useState([]);
  const [selectedCourse, setSelectedCourse] = useState("");

  const [stats, setStats] = useState({
    totalVoterCodes: 0,
    usedCodes: 0,
    totalVotes: 0,
    turnout: 0,
  });

  const positions = [
    "President",
    "Vice President",
    "Secretary",
    "Treasurer",
    "Auditor",
    "Business Manager",
  ];

  const yearLevels = ["1st Year", "2nd Year", "3rd Year", "4th Year"];
  const blocks = ["Block 1", "Block 2", "Block 3"];
  const courses = ["BSIT", "BPA", "BSCS", "BSENTREP", "BTVTED"];

  const token = localStorage.getItem("token");

  const authHeader = {
    headers: { Authorization: `Bearer ${token}` },
  };

  /* ================= FETCH ================= */

  const fetchCodes = async () => {
    try {
      const res = await axios.get(`${API_URL}/codes`, authHeader);
      setCodes(res.data);
    } catch (error) {
      console.error("Error fetching voter codes:", error);
    }
  };

  const fetchStats = async () => {
    try {
      const res = await axios.get(`${API_URL}/stats`, authHeader);
      setStats(res.data);
    } catch (error) {
      console.error("Error fetching statistics:", error);
    }
  };

  useEffect(() => {
    fetchCodes();
    fetchStats();
  }, []);

  /* ================= ACTIONS ================= */

  const generateCodes = async () => {
    const amount = prompt("Enter number of voter codes to generate:");

    if (!amount || isNaN(amount)) {
      alert("Please enter a valid number.");
      return;
    }

    try {
      await axios.post(
        `${API_URL}/codes/generate`,
        { amount: Number(amount) },
        authHeader
      );

      fetchCodes();
      fetchStats();

      alert(`${amount} voter codes generated successfully.`);
    } catch (error) {
      console.error(error);
      alert("Failed to generate codes.");
    }
  };

  const deleteCode = async (id) => {
    if (!window.confirm("Delete this voter code?")) return;

    try {
      await axios.delete(`${API_URL}/codes/${id}`, authHeader);
      fetchCodes();
      fetchStats();
    } catch (error) {
      alert("Failed to delete voter code.");
    }
  };

  /* ================= 🔥 RESET FIXED ================= */

  const resetElection = async () => {
    if (
      !window.confirm(
        "Reset entire election? All votes will be permanently deleted."
      )
    )
      return;

    try {
      const res = await axios.post(
        `${API_URL}/reset-election`,
        {},
        authHeader
      );

      alert(res.data.message || "Election reset successfully.");

      fetchCodes();
      fetchStats();
    } catch (error) {
      console.error("RESET ERROR:", error.response?.data || error.message);
      alert(error.response?.data?.message || "Failed to reset election.");
    }
  };

  /* ================= FORM ================= */

  const handleCancelEdit = () => {
    setCandidateForm({
      firstName: "",
      lastName: "",
      candidacy: "",
      partylist: "",
      yearLevel: "",
      block: "",
      course: "",
      description: "",
      image: null,
    });

    setEditId(null);
  };

  const handleEditClick = (candidate) => {
    setEditId(candidate._id);

    setCandidateForm({
      firstName: candidate.firstName,
      lastName: candidate.lastName,
      candidacy: candidate.candidacy,
      partylist: candidate.partylist || "",
      yearLevel: candidate.yearLevel || "",
      block: candidate.block || "",
      course: candidate.course || "",
      description: candidate.description || "",
      image: null,
    });
  };

  /* ================= FILTER ================= */

  const filteredCandidates = candidates.filter(
    (c) => !selectedCourse || c.course === selectedCourse
  );

  /* ================= UI ================= */

  return (
    <div style={containerStyle(theme)}>
      <h3 style={{ color: theme.text }}>Election Statistics</h3>

      <div style={statsContainer}>
        <StatCard title="Total Codes" value={stats.totalVoterCodes} theme={theme} />
        <StatCard title="Used Codes" value={stats.usedCodes} theme={theme} />
        <StatCard title="Votes Cast" value={stats.totalVotes} theme={theme} />
        <StatCard title="Turnout" value={stats.turnout} theme={theme} />
      </div>

      <button onClick={resetElection} style={resetButton}>
        Reset Election
      </button>

      {/* FORM */}
      <h3 style={{ color: theme.text }}>
        {editId ? "Edit Candidate" : "Add Candidate"}
      </h3>

      <form
        onSubmit={(e) => {
          e.preventDefault();
          onSave();
        }}
        style={formStyle}
      >
        <input
          placeholder="First Name"
          value={candidateForm.firstName}
          onChange={(e) =>
            setCandidateForm({ ...candidateForm, firstName: e.target.value })
          }
          style={inputStyle(theme)}
          required
        />

        <input
          placeholder="Last Name"
          value={candidateForm.lastName}
          onChange={(e) =>
            setCandidateForm({ ...candidateForm, lastName: e.target.value })
          }
          style={inputStyle(theme)}
          required
        />

        <select
          value={candidateForm.candidacy}
          onChange={(e) =>
            setCandidateForm({ ...candidateForm, candidacy: e.target.value })
          }
          style={inputStyle(theme)}
          required
        >
          <option value="">Select Position</option>
          {positions.map((p) => (
            <option key={p}>{p}</option>
          ))}
        </select>

        <select
          value={candidateForm.course}
          onChange={(e) =>
            setCandidateForm({ ...candidateForm, course: e.target.value })
          }
          style={inputStyle(theme)}
        >
          <option value="">Select Course</option>
          {courses.map((c) => (
            <option key={c}>{c}</option>
          ))}
        </select>

        <textarea
          placeholder="Description"
          value={candidateForm.description}
          onChange={(e) =>
            setCandidateForm({ ...candidateForm, description: e.target.value })
          }
          style={inputStyle(theme)}
        />

        <input
          type="file"
          onChange={(e) =>
            setCandidateForm({ ...candidateForm, image: e.target.files[0] })
          }
        />

        <div style={{ display: "flex", gap: 10 }}>
          <button type="submit" style={primaryButton(theme)}>
            {editId ? "Save Changes" : "Add Candidate"}
          </button>

          {editId && (
            <button
              type="button"
              onClick={handleCancelEdit}
              style={cancelButton}
            >
              Cancel
            </button>
          )}
        </div>
      </form>

      {/* FILTER */}
      <h3 style={{ color: theme.text }}>Filter</h3>

      <select
        value={selectedCourse}
        onChange={(e) => setSelectedCourse(e.target.value)}
        style={inputStyle(theme)}
      >
        <option value="">All Courses</option>
        {courses.map((c) => (
          <option key={c}>{c}</option>
        ))}
      </select>

      {/* CANDIDATES */}
      <h3 style={{ color: theme.text }}>Candidates</h3>

      {filteredCandidates.map((c) => (
        <div key={c._id} style={candidateCard(theme)}>
          <div>
            <strong>
              {c.firstName} {c.lastName}
            </strong>
            <br />
            <small>{c.candidacy}</small>
          </div>

          <div style={{ display: "flex", gap: 8 }}>
            <button onClick={() => handleEditClick(c)} style={editButton}>
              Edit
            </button>

            <button onClick={() => onDelete(c._id)} style={deleteButton}>
              Delete
            </button>
          </div>
        </div>
      ))}

      {/* CODES */}
      <div style={codesHeader}>
        <h3 style={{ color: theme.text }}>Voter Codes</h3>

        <button onClick={generateCodes} style={generateButton}>
          Generate Codes
        </button>
      </div>

      <table style={table}>
        <thead>
          <tr>
            <th style={tableCell}>Code</th>
            <th style={tableCell}>Status</th>
            <th style={tableCell}>Action</th>
          </tr>
        </thead>

        <tbody>
          {codes.map((c) => (
            <tr key={c._id}>
              <td style={tableCell}>{c.code}</td>
              <td style={tableCell}>{c.used ? "Used" : "Unused"}</td>
              <td style={tableCell}>
                <button onClick={() => deleteCode(c._id)} style={deleteButton}>
                  Delete
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

/* ===== STYLES ===== */

const StatCard = ({ title, value, theme }) => (
  <div style={{ padding: 10 }}>
    <h4>{title}</h4>
    <p>{value}</p>
  </div>
);

const containerStyle = (theme) => ({
  padding: 20,
  background: theme.card,
});

const statsContainer = { display: "flex", gap: 20 };

const formStyle = { display: "flex", flexDirection: "column", gap: 10 };

const inputStyle = (theme) => ({
  padding: 8,
  background: theme.background,
  color: theme.text,
});

const candidateCard = (theme) => ({
  display: "flex",
  justifyContent: "space-between",
  padding: 10,
  background: theme.background,
});

const primaryButton = (theme) => ({
  background: theme.button,
  color: "#fff",
  padding: 8,
});

const cancelButton = { background: "red", color: "#fff" };

const editButton = { background: "blue", color: "#fff" };

const deleteButton = { background: "red", color: "#fff" };

const generateButton = { background: "green", color: "#fff" };

const resetButton = { background: "red", color: "#fff", padding: 10 };

const codesHeader = { display: "flex", justifyContent: "space-between" };

const table = { width: "100%" };

const tableCell = { border: "1px solid #ccc", padding: 5 };

export default AdminPanel;
